import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "linear",
  // Linear's rail is narrower than shadcn's 16rem default and never draws surface of its own.
  sidebarWidth: "15rem",
};

/* Only what Tailwind classes cannot say — everything else lives in skin.config or theme.css. */

/* Row fills derive from --foreground, so one declaration serves both modes; surfaces and shadows do not. */
[data-skin="linear"] {
  --linear-row-hover: oklch(from var(--foreground) l c h / 0.05);
  --linear-row-active: oklch(from var(--foreground) l c h / 0.08);
  --linear-control-bg: var(--card);
  --linear-control-hover: oklch(from var(--foreground) l c h / 0.04);
  --linear-control-active: oklch(from var(--foreground) l c h / 0.07);

  /* The brand ramp: Linear darkens the indigo on press rather than fading it. */
  --linear-primary-hover: oklch(0.5897 0.1527 276.397); /* #6771d6 */
  --linear-primary-active: oklch(0.5177 0.1507 275.398); /* #525cbd */

  /* Own vars rather than the shared shadow tokens, so each surface tier stays tunable on its own. */
  --linear-control-shadow: 0 1px 1px 0 oklch(from var(--shadow-color) l c h / 0.05);
  --linear-panel-shadow: 0 1px 3px 0 oklch(from var(--shadow-color) l c h / 0.04);
  --linear-menu-shadow:
    0 1px 2px 0 oklch(from var(--shadow-color) l c h / 0.08),
    0 6px 24px -4px oklch(from var(--shadow-color) l c h / 0.14);
  --linear-modal-shadow:
    0 4px 12px 0 oklch(from var(--shadow-color) l c h / 0.1),
    0 20px 70px -10px oklch(from var(--shadow-color) l c h / 0.22);

  --linear-tab-active-bg: var(--card);
  --linear-tab-active-shadow:
    0 0 0 1px var(--border),
    0 1px 2px 0 oklch(from var(--shadow-color) l c h / 0.06);
}

/* Dark: raised surfaces get lighter, not brighter-edged; shadows go deep and neutral. */
:where(.dark) [data-skin="linear"],
.dark[data-skin="linear"] {
  --linear-control-bg: oklch(1 0 0 / 0.05);
  --linear-control-hover: oklch(1 0 0 / 0.09);
  --linear-control-active: oklch(1 0 0 / 0.12);
  --linear-control-shadow: 0 1px 1px 0 oklch(0 0 0 / 0.3);
  --linear-panel-shadow: 0 1px 2px 0 oklch(0 0 0 / 0.25);
  --linear-menu-shadow:
    0 0 0 1px oklch(1 0 0 / 0.04),
    0 8px 32px -4px oklch(0 0 0 / 0.6);
  --linear-modal-shadow:
    0 0 0 1px oklch(1 0 0 / 0.05),
    0 24px 80px -12px oklch(0 0 0 / 0.7);
  --linear-tab-active-bg: oklch(1 0 0 / 0.07);
  --linear-tab-active-shadow: none;
}

/* Body-level, not a utility: type rendering is inherited, so portalled popups pick it up too. */
:root[data-skin="linear"] body {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  letter-spacing: -0.0075em;
  font-feature-settings:
    "cv01" 1,
    "cv02" 1,
    "cv03" 1,
    "cv04" 1,
    "calt" 1,
    "liga" 1;
}

@layer components {
  [data-skin="linear"] :where([data-control-ui="button"][data-control-family="button"][data-slot="root"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"]) {
    --button-press-scale: 1;
    --button-hover-bg: var(--linear-row-hover);
    --button-active-bg: var(--linear-row-active);
    --button-active-hover-bg: var(--linear-row-active);
    --button-focus-shadow: 0 0 0 2px var(--background), 0 0 0 4px var(--ring);
    transition-property: color, background-color, border-color, box-shadow;
  }

  [data-skin="linear"] :where([data-control-ui="button"][data-control-family="button"][data-slot="root"][data-variant="solid"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"][data-variant="solid"]) {
    --button-radius: 9999px;
    --button-hover-bg: var(--linear-primary-hover);
    --button-press-bg: var(--linear-primary-active);
    --button-shadow: var(--linear-control-shadow);
  }

  [data-skin="linear"]
    :where([data-control-ui="button"][data-control-family="button"][data-slot="root"][data-variant="surface"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"][data-variant="surface"]) {
    --button-radius: 9999px;
    --button-bg: var(--linear-control-bg);
    --button-hover-bg: var(--linear-control-hover);
    --button-press-bg: var(--linear-control-active);
    --button-shadow: inset 0 0 0 1px var(--border), var(--linear-control-shadow);
    --button-active-shadow: inset 0 0 0 1px oklch(from var(--primary) l c h / 0.6), var(--linear-control-shadow);
  }

  [data-skin="linear"]
    :where([data-control-ui="button"][data-control-family="button"][data-slot="root"][data-tone="danger"][data-variant="solid"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"][data-tone="danger"][data-variant="solid"]) {
    --button-radius: 9999px;
    --button-hover-bg: var(--destructive);
    --button-press-bg: var(--destructive);
    --button-shadow: var(--linear-control-shadow);
  }

  @media (hover: hover) {
    [data-skin="linear"]
      :where([data-control-ui="button"][data-tone="danger"][data-variant="solid"]:hover, [data-control-ui="toggle"][data-tone="danger"][data-variant="solid"]:hover) {
      filter: brightness(1.05);
    }
  }

  [data-skin="linear"]
    :where([data-control-ui="button"][data-tone="danger"][data-variant="solid"]:active, [data-control-ui="toggle"][data-tone="danger"][data-variant="solid"]:active) {
    filter: brightness(0.95);
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="toolbar"][data-slot="root"][data-variant="inverse"]
        [data-control-ui="button"][data-control-family="button"][data-slot="root"]
    ) {
    --button-bg: transparent;
    --button-foreground: oklch(from var(--background) l c h / 0.7);
    --button-hover-bg: oklch(from var(--background) l c h / 0.1);
    --button-hover-foreground: var(--background);
    --button-press-bg: oklch(from var(--background) l c h / 0.12);
    --button-active-bg: var(--background);
    --button-active-foreground: var(--foreground);
    --button-active-hover-bg: var(--background);
    --button-shadow: 0 0 transparent;
    --button-active-shadow: 0 0 transparent;
  }

  [data-skin="linear"] :where([data-control-ui="button"][data-slot="content"], [data-control-ui="toggle"][data-slot="content"]) {
    gap: 0.375rem;
  }

  /* Re-values the library's pill knobs: a flat ink wash, never a raised card. */
  [data-skin="linear"] :where([data-control-ui="track-highlight"][data-control-family="track-highlight"][data-slot="root"]) {
    --track-highlight-background: var(--linear-row-active);
    --track-highlight-ring-color: transparent;
    --track-highlight-shadow: none;
  }

  /* Re-values the component-local knobs only, so geometry, states, and the `line` variant stay baseline. */
  [data-skin="linear"] :where([data-control-ui="tabs"][data-control-family="tabs"][data-slot="root"]) {
    --tabs-trigger-radius: var(--radius-control);
    --tabs-list-padding: 0rem;
    --tabs-list-background: transparent;
    --tabs-line-border-color: var(--border);
    --tabs-indicator-background: var(--linear-tab-active-bg);
    --tabs-indicator-shadow: var(--linear-tab-active-shadow);
    --tabs-line-indicator-background: var(--primary);
    --tabs-trigger-focus-shadow: 0 0 0 2px oklch(from var(--ring) l c h / 0.45);
  }
}

@layer components {
  [data-skin="linear"] :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"]) {
    --popup-background: var(--popover);
    --popup-border-color: var(--border);
    --popup-shadow: var(--linear-menu-shadow);
  }

  [data-skin="linear"] :where([data-popup-part="item"]) {
    padding: 0.25rem 0.5rem;
    font-size: var(--text-label);
  }

  [data-skin="linear"] :where([data-popup-part="label"]) {
    padding: 0.25rem 0.5rem;
    font-size: var(--text-caption);
    letter-spacing: normal;
    text-transform: none;
  }

  [data-skin="linear"] :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"], [data-control-family="popup"][data-popup-part="bar"]) {
    --popup-item-radius: var(--radius-popup-item);
    --popup-item-highlight-background: var(--linear-row-hover);
    --popup-item-disabled-opacity: 0.4;
    --popup-separator-color: var(--border);
  }

  [data-skin="linear"] :where([data-popup-part="separator"]) {
    margin-inline: 0;
  }

  [data-skin="linear"] :where([data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    font-size: var(--text-caption);
    letter-spacing: normal;
  }

  [data-skin="linear"] :where([data-control-ui="select"][data-control-family="button"][data-slot="trigger"]) {
    --button-radius: var(--radius-control);
    --button-bg: transparent;
    --button-hover-bg: var(--linear-row-hover);
    --button-shadow: inset 0 0 0 1px var(--input);
    --button-press-scale: 1;
    --button-focus-shadow: 0 0 0 2px var(--background), 0 0 0 4px var(--ring);
  }

  [data-skin="linear"]
    :where([data-control-ui="dropdown-menu"][data-control-family="button"][data-slot="trigger"], [data-control-ui="menubar"][data-control-family="button"][data-slot="trigger"]) {
    --button-radius: var(--radius-control);
    --button-bg: transparent;
    --button-hover-bg: var(--linear-row-hover);
    --button-shadow: none;
    --button-press-scale: 1;
    --button-focus-shadow: 0 0 0 2px var(--background), 0 0 0 4px var(--ring);
  }
  [data-skin="linear"]
    :where(
      [data-control-ui="dialog"][data-control-family="popup"][data-popup-part="surface"],
      [data-control-ui="alert-dialog"][data-control-family="popup"][data-popup-part="surface"]
    ) {
    --popup-radius: var(--radius-panel);
    --popup-background: var(--popover);
    --popup-border-color: transparent;
    --popup-border-width: 1px;
    --popup-shadow: var(--linear-modal-shadow);
  }

  .dark [data-skin="linear"]
    :where(
      [data-control-ui="dialog"][data-control-family="popup"][data-popup-part="surface"],
      [data-control-ui="alert-dialog"][data-control-family="popup"][data-popup-part="surface"]
    ) {
    --popup-border-color: var(--border);
  }

  [data-skin="linear"]
    :where([data-control-ui="dialog"][data-slot="title"], [data-control-ui="alert-dialog"][data-slot="title"]) {
    font-size: var(--text-body-lg);
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  [data-skin="linear"] :where([data-control-ui="sheet"][data-control-family="popup"][data-popup-part="surface"]) {
    --popup-background: var(--popover);
    --popup-border-color: var(--border);
    --popup-border-width: 1px;
    --popup-shadow: var(--linear-modal-shadow);
  }

}

@layer components {
  [data-skin="linear"] :where([data-control-family="field"][data-control="true"]) {
    --field-radius: var(--radius-control);
    --field-background: transparent;
    --field-foreground: var(--foreground);
    --field-border-color: var(--input);
    --field-border-width: 1px;
    --field-shadow: 0 0 transparent;
    --field-focus-border-color: var(--primary);
    --field-focus-ring-color: oklch(from var(--ring) l c h / 0.25);
    --field-focus-ring-width: 2px;
  }

  [data-skin="linear"] :where([data-control-ui="combobox"][data-slot="trigger"]) {
    border-radius: var(--radius-control);
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    [data-skin="linear"] :where([data-control-ui="combobox"][data-slot="trigger"]):hover {
      background: var(--linear-row-hover);
    }
  }
}

@layer components {
  [data-skin="linear"] :where([data-control-ui="card"][data-control-family="card"][data-slot="root"]) {
    --card-radius: var(--radius-panel);
    --card-background: var(--card);
    --card-shadow: none;
  }
}
@layer components {
  [data-skin="linear"] :where([data-control-ui="checkbox"][data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]) {
    --choice-radius: max(3px, calc(var(--radius-control) * 0.5));
    --choice-border-color: var(--input);
  }

  [data-skin="linear"] :where([data-control-ui="radio-group"][data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]) {
    --choice-border-color: var(--input);
  }

  [data-skin="linear"] :where([data-control-ui="slider"][data-control-family="range"][data-slot="root"]) {
    --range-indicator-background: var(--primary);
    --range-thumb-radius: 9999px;
    --range-thumb-background: var(--card);
    --range-thumb-border-color: var(--border);
    --range-thumb-shadow: var(--linear-control-shadow);
  }

  [data-skin="linear"] :where([data-control-ui="progress"][data-control-family="range"][data-slot="root"], [data-control-ui="meter"][data-control-family="range"][data-slot="root"]) {
    --range-indicator-background: var(--primary);
  }

  [data-skin="linear"] :where([data-control-ui="thread-rail"][data-control-family="thread-rail"][data-slot="root"]) {
    --thread-rail-popover-background: var(--popover);
    --thread-rail-popover-border-color: var(--border);
    --thread-rail-popover-border-width: 1px;
    --thread-rail-popover-shadow: var(--linear-menu-shadow);
    --thread-rail-item-radius: 9999px;
    --thread-rail-item-background: var(--linear-row-active);
  }

  [data-skin="linear"] :where([data-control-ui="toast"][data-control-family="toast"][data-slot="root"]) {
    --toast-background: var(--popover);
    --toast-border-color: var(--border);
    --toast-border-width: 1px;
    --toast-shadow: var(--linear-menu-shadow);
  }

  [data-skin="linear"] :where([data-control-ui="command"][data-control-family="popup"][data-slot="root"]) {
    --popup-background: var(--popover);
    --popup-border-color: var(--border);
    --popup-border-width: 1px;
    --popup-shadow: var(--linear-menu-shadow);
    overflow: hidden;
  }

  [data-skin="linear"] :where([data-control-ui="command"][data-control-family="popup"][data-popup-part="bar"]) {
    --popup-separator-color: var(--border);
    --popup-item-radius: var(--radius-popup-item);
    --popup-item-highlight-background: var(--linear-row-hover);
    --popup-item-disabled-opacity: 0.4;
    --popup-shortcut-foreground: var(--muted-foreground);
  }

  [data-skin="linear"] :where([data-control-ui="sidebar"][data-slot="menu-button"]) {
    @apply font-medium;
  }


  [data-skin="linear"] :where([data-control-ui="sidebar"][data-control-family="sidebar"][data-slot="root"]) {
    --sidebar-inner-background: transparent;
    --sidebar-inner-border-width: 0px;
    --sidebar-menu-button-radius: var(--radius-control);
    --sidebar-menu-button-foreground: var(--muted-foreground);
    --sidebar-menu-button-hover-background: var(--linear-row-hover);
    --sidebar-menu-button-hover-foreground: var(--foreground);
    --sidebar-menu-button-active-background: var(--linear-row-active);
    --sidebar-menu-button-active-foreground: var(--foreground);
    --sidebar-group-label-foreground: var(--muted-foreground);
  }


  [data-skin="linear"] :where([data-control-ui="sidebar"][data-slot="group-label"]) {
    @apply px-2 text-caption font-medium;
  }

  [data-skin="linear"] :where([data-control-ui="sidebar-layout"][data-slot="content"]) {
    @apply rounded-[var(--radius-panel)] border-border bg-card shadow-(--linear-panel-shadow);
  }

  [data-skin="linear"] :where([data-control-ui="tree"][data-control-family="tree"][data-slot="root"]) {
    --tree-item-trigger-radius: var(--radius-control);
    --tree-item-trigger-foreground: var(--muted-foreground);
    --tree-item-trigger-hover-background: var(--linear-row-hover);
    --tree-item-trigger-hover-foreground: var(--foreground);
    --tree-item-trigger-selected-background: var(--linear-row-active);
    --tree-item-trigger-selected-foreground: var(--foreground);
    --tree-item-trigger-font-size: var(--text-label);
    --tree-item-trigger-selected-font-weight: 500;
  }


  [data-skin="linear"] :where([data-control-ui="alert"][data-control-family="alert"][data-slot="root"]) {
    --alert-radius: var(--radius-panel);
    --alert-background: var(--card);
    --alert-shadow: none;
  }

  [data-skin="linear"] :where([data-control-ui="item"][data-control-family="item"][data-slot="root"]) {
    --item-radius: var(--radius-control);
    --item-hover-background: var(--linear-row-hover);
    --item-active-scale: 1;
  }

  [data-skin="linear"] :where([data-control-ui="empty"][data-control-family="empty"][data-slot="root"]) {
    --empty-radius: var(--radius-panel);
    --empty-background: transparent;
    --empty-border-color: var(--border);
    --empty-border-width: 1px;
    --empty-border-style: dashed;
  }

  [data-skin="linear"] :where([data-control-ui="badge"][data-control-family="badge"][data-slot="root"]) {
    --badge-radius: 9999px;
  }

  [data-skin="linear"] :where([data-control-ui="kbd"][data-slot="root"]) {
    @apply rounded-[calc(var(--radius-control)*0.67)] bg-transparent text-muted-foreground shadow-none ring-border;
  }

  [data-skin="linear"] :where([data-control-ui="scroll-area"][data-control-family="scroll-area"][data-slot="root"]) {
    --scroll-area-thumb-radius: 9999px;
    --scroll-area-thumb-background: oklch(from var(--foreground) l c h / 0.2);
  }

  [data-skin="linear"] :where([data-control-ui="chat-layout"][data-slot="root"]) {
    @apply rounded-[var(--radius-scene)] border-border bg-card shadow-(--linear-panel-shadow);
  }

  [data-skin="linear"] :where([data-control-ui="chat-message"][data-control-family="chat-message"][data-slot="root"]) {
    --chat-message-avatar-radius: 9999px;
    --chat-message-avatar-background: var(--linear-control-bg);
    --chat-message-avatar-border-color: var(--border);
    --chat-message-avatar-border-width: 1px;
  }

  [data-skin="linear"] :where([data-control-ui="chat-composer"][data-control-family="chat-composer"][data-slot="root"]) {
    --chat-composer-shell-background: var(--card);
    --chat-composer-shell-border-color: var(--border);
    --chat-composer-shell-radius: var(--radius-field);
    --chat-composer-shell-shadow: var(--linear-panel-shadow);
    --chat-composer-mention-radius: var(--radius-control);
    --chat-composer-mention-border-color: var(--border);
    --chat-composer-mention-border-width: 1px;
    --chat-composer-mention-background: var(--linear-row-hover);
  }

  [data-skin="linear"] :where([data-control-ui="chat-composer"][data-slot="submit"]) {
    @apply rounded-full bg-[var(--primary)] text-[var(--primary-foreground)] shadow-(--linear-control-shadow) hover:bg-[var(--linear-primary-hover)] active:bg-[var(--linear-primary-active)] transition-[background-color,border-color,box-shadow,color] duration-[var(--duration-fast)] ease-[var(--ease-standard)] active:scale-100 focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-background;
  }


  [data-skin="linear"] :where([data-control-ui="markdown-block"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] bg-card shadow-none ring-0;
  }

  [data-skin="linear"] :where([data-control-ui="markdown-block"][data-slot="header"]) {
    @apply border-b border-border bg-transparent;
  }

  [data-skin="linear"] :where([data-control-ui="code"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] bg-card shadow-none ring-border;
  }

  [data-skin="linear"] :where([data-control-ui="code"][data-slot="header"]) {
    @apply border-b border-border bg-transparent;
  }

  [data-skin="linear"] :where([data-control-ui="code"][data-slot="title"]) {
    @apply font-mono text-caption text-muted-foreground;
  }

  [data-skin="linear"] :where([data-control-ui="code-diff"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] bg-card shadow-none ring-border;
  }

  [data-skin="linear"] :where([data-control-ui="code-diff"][data-slot="header"]) {
    @apply border-b border-border bg-transparent;
  }

  [data-skin="linear"] :where([data-control-ui="inline-attachment"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] bg-card shadow-none ring-border;
  }

  [data-skin="linear"] :where([data-control-ui="inline-attachment"][data-slot="image"]) {
    @apply rounded-[var(--radius-control)];
  }

}

@layer components {
  [data-skin="linear"] :where([data-control-ui="chat-message"][data-control-family="chat-message"][data-slot="root"][data-role="user"]) {
    --chat-message-radius: var(--radius-field);
    --chat-message-corner-radius: var(--radius-field);
    --chat-message-background: var(--primary);
    --chat-message-shadow: none;
    --chat-message-foreground: var(--primary-foreground);
  }

  [data-skin="linear"] :where([data-control-ui="chat-message"][data-control-family="chat-message"][data-slot="root"][data-role="assistant"]) {
    --chat-message-radius: var(--radius-field);
    --chat-message-corner-radius: var(--radius-field);
    --chat-message-background: transparent;
  }
}

/* Hairline borders instead of elevation; floating surfaces are the only things allowed a real shadow. */

[data-skin="linear"] {
  /* Inter, self-hosted by the app shell (next/font fills --font-inter); host without it falls to the system stack. */
  --font-sans: var(--font-inter, "Inter"), "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Berkeley Mono", ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace;

  /* Type scale: Linear runs one flat 13px band for ALL chrome (nav rows, controls, body) and reserves
     the larger rungs for content headings. Label == body on purpose. */
  --text-label: 0.8125rem; /* 13px — sm controls, nav rows, tooltips */
  --text-body: 0.8125rem; /* 13px — THE workhorse */
  --text-body-lg: 0.9375rem; /* 15px */

  /* Headings stay tight and semibold; no 700 anywhere (Linear tops out at semibold). */
  --text-heading-4: 0.875rem;
  --text-heading-3: 1rem;
  --text-heading-3--line-height: 1.4;
  --text-heading-2: 1.1875rem;
  --text-heading-2--line-height: 1.3;
  --text-heading-1: 1.5rem; /* 24px — the issue-title rung */
  --text-heading-1--line-height: 1.25;
  --text-heading-1--font-weight: 600;
  --text-heading-1--letter-spacing: -0.014em;
  --text-display: 2rem;
  --text-display--line-height: 1.15;
  --text-display--letter-spacing: -0.022em;

  /* Light: pure-white surfaces on a cool gray paper. card == background so the shell's content frame
     reads as the one white sheet Linear floats its whole app on. */
  --background: oklch(1 0 0);
  --foreground: oklch(0.2228 0.0079 274.573); /* #1a1b1f */
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2228 0.0079 274.573);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2228 0.0079 274.573);
  --primary: oklch(0.5674 0.1585 275.206); /* #5e6ad2 — THE Linear indigo */
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.9614 0.0013 286.375); /* #f2f2f3 */
  --muted-foreground: oklch(0.5401 0.0124 280.281); /* #6d6e76 */
  --secondary: oklch(0.9614 0.0013 286.375);
  --secondary-foreground: oklch(0.2228 0.0079 274.573);
  --accent: oklch(0.9434 0.0013 286.374); /* #ececed — hover / selection fill */
  --accent-foreground: oklch(0.2228 0.0079 274.573);
  --destructive: oklch(0.576 0.1835 23.679);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.9255 0.0027 286.347 / var(--ring-opacity)); /* #e6e6e8 hairline */
  --input: oklch(0.9042 0.0027 286.346); /* #dfdfe1 — fields carry a touch more edge */
  --ring: oklch(0.5674 0.1585 275.206); /* focus == brand */
  --canvas: oklch(0.9734 0.0013 286.375); /* #f6f6f7 — the paper the white sheet sits on */


  /* Surfaces are opaque: no glass anywhere. The modal scrim is the only dim. */
  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.3;
  --backdrop-blur-overlay: 0px;
  --scroll-fade-size: 1.5rem;

  /* Elevation is EARNED here: controls and panels are held by hairlines, only floating surfaces lift.
     Hence a near-zero control tier, a 1x panel tier, and popover/modal tiers pushed way up. */
  --shadow-color: oklch(0.2217 0.0084 264.39);
  --shadow-highlight: oklch(1 0 0 / 0.08); /* matte: a whisper of top light, not a lit-paper rim */
  --shadow-size: 1;
  --shadow-opacity: 0.75;
  --shadow-control-multiplier: 0.6;
  --shadow-panel-multiplier: 1;
  --shadow-popover-multiplier: 5;
  --shadow-modal-multiplier: 8;

  /* THE radius knob: 4px. Controls ride 1.5x (6px), panels 3x (12px) — small, never pill-shaped by
     token (the button pill is a deliberate slot choice, not a radius side effect). */
  --radius: 0.25rem;
  --radius-control: calc(var(--radius) * 1.5);
  --radius-field: calc(var(--radius) * 2); /* 8px — composer shell, user bubble */
  --radius-panel: calc(var(--radius) * 3); /* 12px — dialogs, code, the content sheet */
  --radius-scene: calc(var(--radius) * 3.5); /* 14px */

  /* Concentric floating-list geometry is authored here so the pack owns the exact 4px-derived ratios. */
  --popover-padding: 0.25rem;
  /* Rows carry the SAME 6px corner as controls (Linear has one row corner everywhere: menus, nav,
     tree, and the sliding selection pill, which the library shapes from this token). */
  --radius-popup-item: var(--radius-control);

  --padding-x: 0.75rem;
  --padding-y: 0.5rem;

  /* Control ramp: 32px base, so `sm` lands on Linear's 28px button. */
  --control-h: 2rem;

  /* Motion is a snap, not a glide — Linear's whole feel rests on this. */
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-emphasized: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 90ms;
  --duration-base: 130ms;
  --duration-slow: 200ms;
}

/* Dark tokens: the real Linear night — near-black canvas, panel one step up, popups two. */
:where(.dark) [data-skin="linear"],
.dark[data-skin="linear"] {
  --background: oklch(0.1739 0.0041 285.967); /* #101012 */
  --foreground: oklch(0.9784 0.0011 197.139); /* #f7f8f8 */
  --card: oklch(0.1739 0.0041 285.967);
  --card-foreground: oklch(0.9784 0.0011 197.139);
  --popover: oklch(0.2277 0.0057 285.935); /* #1c1c1f — menus sit above the sheet */
  --popover-foreground: oklch(0.9784 0.0011 197.139);
  --primary: oklch(0.5674 0.1585 275.206);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.2277 0.0057 285.935);
  --muted-foreground: oklch(0.6488 0.0146 262.359); /* #8a8f98 */
  --secondary: oklch(0.2277 0.0057 285.935);
  --secondary-foreground: oklch(0.9784 0.0011 197.139);
  --accent: oklch(0.2494 0.0075 285.844); /* #212125 */
  --accent-foreground: oklch(0.9784 0.0011 197.139);
  --destructive: oklch(0.576 0.1835 23.679);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.2618 0.0113 278.089 / var(--ring-opacity)); /* #23242a */
  --input: oklch(0.2986 0.0109 278.197);
  --ring: oklch(0.6102 0.1404 276.317); /* the indigo lifts a rung to stay legible on ink */
  --canvas: oklch(0.139 0.0029 246.256); /* #08090a */
  --shadow-color: oklch(0 0 0);
  --shadow-highlight: oklch(1 0 0 / 0.05);
  --shadow-opacity: 1;
}

/* prefers-reduced-motion: token-driven, so every derived tempo flattens together. */
@media (prefers-reduced-motion: reduce) {
  [data-skin="linear"] {
    --duration-fast: 0ms;
    --duration-base: 0ms;
    --duration-slow: 0ms;
  }
}
